export interface ConnectorConfig {
  stripeSecretKey: string;
  fetch?: typeof fetch;
}

export interface HubSpotWebhookEvent {
  objectId: number;
  propertyName: string;
  propertyValue: string;
  changeSource: string;
  eventId: string;
  subscriptionId: string;
  portalId: string;
  appId: string;
  occurredAt: number;
  subscriptionType: string;
  attemptNumber: number;
  email?: string;
  firstname?: string;
  lastname?: string;
}

export type HubSpotWebhookPayload = HubSpotWebhookEvent[];

export interface HandleResult {
  customerIds: string[];
}

async function fetchContactDetails(
  objectId: number,
  config: ConnectorConfig
): Promise<{ email: string; firstname: string; lastname: string }> {
  const fetchFn = config.fetch ?? fetch;
  const hubspotApiKey = process.env.HUBSPOT_API_KEY;
  if (!hubspotApiKey) {
    throw new Error('HUBSPOT_API_KEY environment variable is required to fetch contact details');
  }
  const response = await fetchFn(`https://api.hubapi.com/crm/v3/objects/contacts/${objectId}`, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`Failed to fetch contact ${objectId}: ${response.status} ${response.statusText}`);
  }
  const data = (await response.json()) as { email: string; firstname: string; lastname: string };
  return { email: data.email, firstname: data.firstname, lastname: data.lastname };
}

export async function handle(payload: HubSpotWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!Array.isArray(payload)) {
    throw new Error('Payload must be an array of webhook events');
  }
  if (!config.stripeSecretKey) {
    throw new Error('stripeSecretKey is required in config');
  }

  const fetchFn = config.fetch ?? fetch;
  const customerIds: string[] = [];

  for (const event of payload) {
    if (event.propertyName !== 'lifecycle_stage' || event.propertyValue !== 'customer') {
      continue;
    }

    let email = event.email;
    let firstname = event.firstname;
    let lastname = event.lastname;

    if (!email || !firstname || !lastname) {
      if (!event.objectId) {
        throw new Error(`Event ${event.eventId} missing objectId and contact details (email, firstname, lastname)`);
      }
      const details = await fetchContactDetails(event.objectId, config);
      email = details.email;
      firstname = details.firstname;
      lastname = details.lastname;
    }

    if (!email) throw new Error(`Event ${event.eventId} missing required field: email`);
    if (!firstname) throw new Error(`Event ${event.eventId} missing required field: firstname`);
    if (!lastname) throw new Error(`Event ${event.eventId} missing required field: lastname`);

    const stripeBody = {
      email,
      name: `${firstname} ${lastname}`.trim(),
    };

    const response = await fetchFn('https://api.stripe.com/v1/customers', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.stripeSecretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams(stripeBody).toString(),
    });

    if (!response.ok) {
      const errorText = await response.text().catch(() => '');
      throw new Error(`Stripe API error (POST https://api.stripe.com/v1/customers): ${response.status} ${response.statusText} - ${errorText}`);
    }

    const customer = (await response.json()) as { id: string };
    customerIds.push(customer.id);
  }

  return { customerIds };
}

